	n := 0
	for len(xs) >= 8 {
		a := (*[8]uint64)(xs)
		n += bits.OnesCount64(a[0]) + bits.OnesCount64(a[1]) +
			bits.OnesCount64(a[2]) + bits.OnesCount64(a[3]) +
			bits.OnesCount64(a[4]) + bits.OnesCount64(a[5]) +
			bits.OnesCount64(a[6]) + bits.OnesCount64(a[7])
		xs = xs[8:]
	}
	if len(xs) >= 4 {
		n += bits.OnesCount64(xs[0]) + bits.OnesCount64(xs[1]) +
			bits.OnesCount64(xs[2]) + bits.OnesCount64(xs[3])
		xs = xs[4:]
	}
	for _, x := range xs {
		n += bits.OnesCount64(x)
	}
	return n
}

